class LongTermMemory:
  def store(self, content, importance=0.5):
    embedding = embed(content)
    memory_store.upsert({"id": uuid4(), "content": content,
      "embedding": embedding, "importance": importance, "decay": 1.0})
  def retrieve(self, query, top_k=5):
    results = memory_store.search(embed(query), limit=top_k)
    return sorted(results, key=lambda r: r.importance * r.decay * r.similarity, reverse=True)

