import random
from collections import defaultdict
def deduplicate_and_balance(dataset):
  seen = set()
  unique = [d for d in dataset if (k:=hash(d["instruction"]+d["output"])) not in seen and not seen.add(k)]
  by_type = defaultdict(list)
  for d in unique: by_type[d["task_type"]].append(d)
  mn = min(len(v) for v in by_type.values())
  return sum([random.sample(v, mn) for v in by_type.values()], [])

